public struct ReplaceDocumentIntent: AppIntent {
    public static let title: LocalizedStringResource = "Replace Markdown Document"
    public static let description = IntentDescription("Replaces a document's whole Markdown. It overwrites every line, so it asks first: without confirmed: true it changes nothing and says what to ask the person. Send confirmed: true only after the person has said yes.")

    @Parameter(title: "Markdown", description: "The Markdown that becomes the document's whole text.")
    public var markdown: String
    @Parameter(title: "Document", description: "The document: its name as list_documents shows it (\"Plan\"), or its path, absolute or relative to a served folder.", requestValueDialog: "Which document?")
    public var document: MarkdownDocumentEntity

