    }

    public var input: ReplaceDocumentInput {
        ReplaceDocumentInput(markdown: markdown, document: document.id)
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        // Consequential: the person says yes before it acts.
        try await requestConfirmation()
        let input = self.input
        let result: Result<ReplaceDocumentOutput, any Error>
        do { result = .success(try await ReplaceDocumentAction.run(input)) } catch { result = .failure(error) }
        if let dialog = ReplaceDocumentAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
        return .result(dialog: "Done.")
    }
}

